1	/**
2	 * Event Registry — modules declare event metadata here.
3	 * Engine uses registries instead of hardcoding module-specific event types.
4	 *
5	 * Flags: boolean properties on event types/sources (engine checks flags, not category names).
6	 * Categories: modules group their events for internal use.
7	 * Labels: human-readable display names for event types.
8	 * Goal cleanup: which goal types to complete when an event fires.
9	 * Belief zeroing: which events should zero out investigator beliefs about a suspect.
10	 */
11	import type { Agent } from './agent';
12	
13	/** Callback for adding mood modifiers from module code (SPEC-mood-modifiers) */
14	export type MoodModifierCallback = (npcId: string, mod: {
15	  source: string; category: string; magnitude: number;
16	  remaining: number; duration: number; decay: 'exponential' | 'linear' | 'none';
17	}) => void;
18	
19	// ─── Event Type Flags ───
20	// Engine defines WHAT properties exist. Modules declare WHICH event types have them.
21	// Same pattern as AgentProfile capability flags (investigator, detersCrime, canSentence).
22	
23	export interface EventTypeFlags {
24	  /** Beliefs about these events should transfer between agents during interactions */
25	  transferable?: boolean;
26	  /** Purely informational events — skip reactive volition evaluation */
27	  informationOnly?: boolean;
28	  /** Subject of this event should be included as reactor in reactive volition (e.g., criminal reacts to WANTED_STATUS by fleeing) */
29	  subjectReacts?: boolean;
30	  /** Multiplier for belief decay rate. Default 1.0. Lower = slower decay (e.g. 0.1 = 10x slower). */
31	  decayRate?: number;
32	}
33	
34	const EVENT_TYPE_FLAGS: Map<string, EventTypeFlags> = new Map();
35	
36	/** Register flags for event types. Modules call this to declare properties. */
37	export function registerEventTypeFlags(eventType: string, flags: EventTypeFlags): void {
38	  const existing = EVENT_TYPE_FLAGS.get(eventType) ?? {};
39	  EVENT_TYPE_FLAGS.set(eventType, { ...existing, ...flags });
40	}
41	
42	/** Batch register same flags for multiple event types */
43	export function registerEventTypeFlagsBatch(eventTypes: string[], flags: EventTypeFlags): void {
44	  for (const t of eventTypes) registerEventTypeFlags(t, flags);
45	}
46	
47	/** Check if beliefs about this event type should transfer during interactions */
48	export function isTransferable(eventType: string): boolean {
49	  return EVENT_TYPE_FLAGS.get(eventType)?.transferable === true;
50	}
51	
52	/** Check if this event type is purely informational (skip reactive volition) */
53	export function isInformationOnly(eventType: string): boolean {
54	  return EVENT_TYPE_FLAGS.get(eventType)?.informationOnly === true;
55	}
56	
57	/** Check if the subject of this event should react (e.g., criminal flees on WANTED_STATUS) */
58	export function subjectReacts(eventType: string): boolean {
59	  return EVENT_TYPE_FLAGS.get(eventType)?.subjectReacts === true;
60	}
61	
62	/** Get decay rate multiplier for event type. Default 1.0. Motives use 0.05–0.2 for slow decay. */
63	export function getEventTypeDecayRate(eventType: string): number {
64	  return EVENT_TYPE_FLAGS.get(eventType)?.decayRate ?? 1.0;
65	}
66	
67	// ─── Source Flags ───
68	// Same pattern: engine defines WHAT source properties exist, modules assign them.
69	
70	export interface SourceFlags {
71	  /** Source indicates perpetrator involvement */
72	  perpetrator?: boolean;
73	  /** Source is from firsthand experience */
74	  firsthand?: boolean;
75	  /** Source involves hiding/covering up */
76	  concealment?: boolean;
77	}
78	
79	const SOURCE_FLAGS: Map<string, SourceFlags> = new Map();
80	
81	export function registerSourceFlags(source: string, flags: SourceFlags): void {
82	  const existing = SOURCE_FLAGS.get(source) ?? {};
83	  SOURCE_FLAGS.set(source, { ...existing, ...flags });
84	}
85	
86	export function getAllRegisteredSources(): string[] { return Array.from(SOURCE_FLAGS.keys()); }
87	
88	export function isPerpetrator(source: string | null | undefined): boolean {
89	  return source != null && (SOURCE_FLAGS.get(source)?.perpetrator === true);
90	}
91	
92	export function isFirsthand(source: string | null | undefined): boolean {
93	  return source != null && (SOURCE_FLAGS.get(source)?.firsthand === true);
94	}
95	
96	export function isConcealment(source: string | null | undefined): boolean {
97	  return source != null && (SOURCE_FLAGS.get(source)?.concealment === true);
98	}
99	
100	// ─── Event Categories (module-internal, NOT used by engine logic) ───
101	const EVENT_CATEGORIES: Map<string, Set<string>> = new Map();
102	
103	export function registerEventCategory(category: string, eventTypes: string[]): void {
104	  const set = EVENT_CATEGORIES.get(category) ?? new Set();
105	  for (const t of eventTypes) set.add(t);
106	  EVENT_CATEGORIES.set(category, set);
107	}
108	
109	export function isEventCategory(eventType: string, category: string): boolean {
110	  return EVENT_CATEGORIES.get(category)?.has(eventType) ?? false;
111	}
112	
113	export function getEventTypesByCategory(category: string): string[] {
114	  return Array.from(EVENT_CATEGORIES.get(category) ?? []);
115	}
116	
117	/** Get all registered event types across all categories (for IL context, prompts, etc.) */
118	export function getAllRegisteredEventTypes(): string[] {
119	  const all = new Set<string>();
120	  for (const types of EVENT_CATEGORIES.values()) {
121	    for (const t of types) all.add(t);
122	  }
123	  return Array.from(all);
124	}
125	
126	// ─── Event Display Labels ───
127	// Human-readable names for event types (used in prompts, display text)
128	const EVENT_LABELS: Map<string, string> = new Map();
129	
130	export function registerEventLabels(labels: Record<string, string>): void {
131	  for (const [eventType, label] of Object.entries(labels)) {
132	    EVENT_LABELS.set(eventType, label);
133	  }
134	}
135	
136	export function getEventLabel(eventType: string): string | null {
137	  return EVENT_LABELS.get(eventType) ?? null;
138	}
139	
140	/** Get event label with warning if unregistered. For display text where null is not acceptable. */
141	export function getEventLabelSafe(eventType: string, fallback = 'an incident'): string {
142	  const label = EVENT_LABELS.get(eventType);
143	  if (!label) {
144	    console.warn(`  [Registry] No label registered for event type "${eventType}" — using fallback "${fallback}"`);
145	  }
146	  return label ?? fallback;
147	}
