416	// ─── Status Categories ───
417	// Modules register which statuses mean "active" (can act) vs "absent" (not in world)
418	const ACTIVE_STATUSES: Set<string> = new Set(); // null/undefined = active by default
419	const ABSENT_STATUSES: Set<string> = new Set();
420	
421	export function registerActiveStatuses(statuses: string[]): void {
422	  for (const s of statuses) ACTIVE_STATUSES.add(s);
423	}
424	
425	export function registerAbsentStatuses(statuses: string[]): void {
426	  for (const s of statuses) ABSENT_STATUSES.add(s);
427	}
428	
429	export function isStatusActive(status: string | null | undefined): boolean {
430	  if (!status) return true; // null/undefined = default free state = active
431	  return ACTIVE_STATUSES.has(status);
432	}
433	
434	export function isStatusAbsent(status: string | null | undefined): boolean {
435	  if (!status) return false; // null/undefined = default free state = not absent
436	  return ABSENT_STATUSES.has(status);
437	}
