560	// ─── Discovery Handlers ───
561	// Modules register how to process discoveries (e.g., body found → memory, mood, belief, grief).
562	// Engine detects discovery condition (dead+alive co-location). Module defines the response.
563	export interface DiscoveryContext {
564	  discoverer: Agent;
565	  victimId: string;
566	  affectedName: string;
567	  location: string;
568	  gameDay: number;
569	  /** Event type from associated scene (e.g., 'NPC_KILLED'). null if no scene. */
570	  deathEventType: string | null;
571	  /** Add a mood modifier to an NPC (SPEC-mood-modifiers) */
572	  addMoodModifier: MoodModifierCallback;
573	}
