1	/**
2	 * Social Module — universal social behavior for NPC-NPC conversations.
3	 *
4	 * Registers:
5	 * - Topic sources that drive NPC conversation topics
6	 * - Social affordances (socialize) for proactive social behavior
7	 *
8	 * This is CONTENT (what NPCs do/talk about), not ENGINE (how it's selected).
9	 */
10	
11	import { TOPIC_SOURCE_REGISTRY, AFFORDANCE_REGISTRY, TARGET_FINDERS, registerTopicGroupMapping, isStatusAbsent } from '@clwa/engine';
12	import type { Agent, AffordanceContext, AffordanceTarget } from '@clwa/engine';
13	import { SOCIAL_TOPIC_SOURCES } from './topic-sources';
14	
15	/** Find a nearby NPC to socialize with (same or adjacent location) */
16	function findSocializeTarget(npcId: string, agent: Agent, ctx: AffordanceContext): AffordanceTarget | null {
17	  // Prefer co-located NPC
18	  for (const [otherId, other] of ctx.agents) {
19	    if (otherId === npcId || !other.state.alive || other.profile.isPlayer) continue;
20	    if (isStatusAbsent(other.state.status)) continue;
21	    if (other.state.location === agent.state.location) {
22	      return { targetId: otherId, targetName: other.profile.name, targetLocation: other.state.location };
23	    }
24	  }
25	  // Try adjacent locations
26	  const loc = ctx.locations.get(agent.state.location);
27	  if (loc) {
28	    for (const connId of loc.connections) {
29	      for (const [otherId, other] of ctx.agents) {
30	        if (otherId === npcId || !other.state.alive || other.profile.isPlayer) continue;
31	        if (isStatusAbsent(other.state.status)) continue;
32	        if (other.state.location === connId) {
33	          return { targetId: otherId, targetName: other.profile.name, targetLocation: connId };
34	        }
35	      }
36	    }
37	  }
38	  return null;
39	}
40	
41	export function registerSocialModule(): void {
42	  // Register all social topic sources
43	  TOPIC_SOURCE_REGISTRY.push(...SOCIAL_TOPIC_SOURCES);
44	
45	  // Topic group mappings — maps categories to diversity groups
46	  registerTopicGroupMapping({
47	    'casual': 'casual', 'casual:': 'casual', 'idle': 'casual',
48	    'event:': 'event', 'memory': 'event',
49	    'relationship': 'relationship', 'grief': 'relationship', 'opinion': 'relationship',
50	    'mood': 'mood',
51	    'inner': 'inner',
52	    'role:': 'knowledge', 'fact': 'knowledge', 'fact:': 'knowledge', 'question': 'knowledge',
53	  });
54	
55	  // Social affordance — triggers LLM volition for extraverted NPCs even without crime events.
56	  // No actionVerb — doesn't appear in LLM action list. Provides instinct pressure only.
57	  // LLM chooses go/talk/wait freely. With socialOnly flag, "talk" becomes move-only → TopicEngine handles conversation.
58	  AFFORDANCE_REGISTRY.push({
59	    id: 'socialize',
60	    label: 'Seek out someone to talk to — the quiet gets to you',
61	    category: 'social',
62	    severity: 0,
63	    requires: { notGuard: true },
64	    weights: [
65	      { trait: 'E', direction: 'high', multiplier: 0.4 },  // E=0.9→0.36, E=0.5→0.20
66	      { trait: 'A', direction: 'high', multiplier: 0.1 },  // A=0.7→0.07
67	    ],
68	    moodWeight: 0,                // personality-driven, not mood-driven
69	    relationshipWeight: 0.0,
70	    goalType: 'visit',
71	    goalPriority: 2,              // below schedule(3), doesn't interfere with routine
72	    socialOnly: true,             // engine uses this flag for social-only detection (no hardcoded IDs)
73	    stepTemplates: [
74	      { action: 'move_to', location: '$target', skipIfAt: true },
75	    ],
76	  });
77	  TARGET_FINDERS.set('socialize', findSocializeTarget);
78	
79	  console.log(`[Social] Registered ${SOCIAL_TOPIC_SOURCES.length} topic sources + socialize affordance`);
80	}
